ALTER TABLE "who_dataset" ADD COLUMN "sealed" boolean DEFAULT false NOT NULL;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION who_reference_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP = 'UPDATE' AND TG_TABLE_NAME = 'who_dataset' AND NOT OLD.sealed AND NEW.sealed AND ROW(NEW.id, NEW.publisher, NEW.standard, NEW.version, NEW.publication_date, NEW.retrieved_at, NEW.source_url, NEW.sha256, NEW.indicator, NEW.sex, NEW.position, NEW.x_unit, NEW.min_x, NEW.max_x, NEW.row_count, NEW.imported_at) IS NOT DISTINCT FROM ROW(OLD.id, OLD.publisher, OLD.standard, OLD.version, OLD.publication_date, OLD.retrieved_at, OLD.source_url, OLD.sha256, OLD.indicator, OLD.sex, OLD.position, OLD.x_unit, OLD.min_x, OLD.max_x, OLD.row_count, OLD.imported_at) THEN IF (SELECT count(*) FROM who_reference_row WHERE dataset_id = OLD.id) <> OLD.row_count THEN RAISE EXCEPTION 'WHO dataset cannot seal incomplete rows'; END IF; RETURN NEW; END IF; RAISE EXCEPTION 'WHO reference datasets and rows are immutable'; END $$;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION who_row_matches_dataset() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE d who_dataset%ROWTYPE; BEGIN SELECT * INTO d FROM who_dataset WHERE id = NEW.dataset_id FOR UPDATE; IF d.sealed THEN RAISE EXCEPTION 'WHO dataset is sealed'; END IF; IF NEW.indicator <> d.indicator OR NEW.sex <> d.sex OR NEW.x_unit <> d.x_unit OR NEW.x < d.min_x OR NEW.x > d.max_x OR (d.indicator = 'HEIGHT_FOR_AGE' AND NEW.position IS DISTINCT FROM (CASE WHEN NEW.x <= 730 THEN 'RECUMBENT' ELSE 'STANDING' END)) OR (d.indicator <> 'HEIGHT_FOR_AGE' AND NEW.position IS DISTINCT FROM d.position) OR (NEW.x_unit = 'DAY' AND NEW.x <> trunc(NEW.x)) OR (NEW.x_unit = 'CM' AND NEW.x * 10 <> trunc(NEW.x * 10)) THEN RAISE EXCEPTION 'WHO row does not match dataset'; END IF; RETURN NEW; END $$;